        CaptionLine(
          start: Duration(milliseconds: 471750),
          end: Duration(milliseconds: 473017),
          text: '“What should he do?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 474504),
          end: Duration(milliseconds: 477136),
          text: 'Akhlaq answered before Nadir could.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 477136),
          end: Duration(milliseconds: 477684),
          text: '“Leave.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 477684),
          end: Duration(milliseconds: 479328),
          text: '“Even if they laugh?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 479328),
          end: Duration(milliseconds: 479657),
          text: '“Yes.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 479809),
          end: Duration(milliseconds: 482271),
          text: '“Even if they call him strange?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 482271),
          end: Duration(milliseconds: 483809),
          text: 'Akhlaq hesitated.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 483809),
          end: Duration(milliseconds: 485485),
          text: 'Then he looked towards Lut (A.S.).',
        ),
        CaptionLine(
          start: Duration(milliseconds: 486809),
          end: Duration(milliseconds: 487128),
          text: '“Yes.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 487128),
          end: Duration(milliseconds: 491809),
          text: 'A louder argument began in another part of the street.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 491809),
          end: Duration(milliseconds: 493684),
          text: 'People were speaking against Lut (A.S.).',
        ),
        CaptionLine(
          start: Duration(milliseconds: 494809),
          end: Duration(milliseconds: 498809),
          text: 'But Imaan noticed something unusual.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 498809),
          end: Duration(milliseconds: 502508),
          text: 'They were not proving his message wrong.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 502508),
          end: Duration(milliseconds: 507381),
          text: 'Instead, they were annoyed that he kept reminding them.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 507381),
          end: Duration(milliseconds: 513847),
          text:
              'One person complained that Lut and those with him wanted to remain pure.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 514614),
          end: Duration(milliseconds: 515381),
          text: 'Akhlaq blinked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 515381),
          end: Duration(milliseconds: 518139),
          text: '“They are angry because he does not want to join them?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 518139),
          end: Duration(milliseconds: 518468),
          text: 'Nadir nodded.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 519793),
          end: Duration(milliseconds: 524793),
          text: '“That can happen when wrong behaviour becomes normal.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 524793),
          end: Duration(milliseconds: 525793),
          text: '“What?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 525793),
          end: Duration(milliseconds: 530793),
          text:
              '“Sometimes a person who refuses to join makes other people uncomfortable.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 531364),
          end: Duration(milliseconds: 532793),
          text: 'Imaan understood.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 532793),
          end: Duration(milliseconds: 537793),
          text:
              '“Because his refusal reminds them that there is still another choice.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 537793),
          end: Duration(milliseconds: 539793),
          text: 'The Compass became brighter.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 540754),
          end: Duration(milliseconds: 542554),
          text: 'Akhlaq looked towards Lut (A.S.).',
        ),
        CaptionLine(
          start: Duration(milliseconds: 543385),
          end: Duration(milliseconds: 548385),
          text:
              'He stood among people who had grown comfortable with what he was warning them against.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 548385),
          end: Duration(milliseconds: 554185),
          text:
              'Yet he did not change Allah’s message just because people disliked hearing it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 554616),
          end: Duration(milliseconds: 555801),
          text: 'Imaan said quietly:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 555801),
          end: Duration(milliseconds: 559465),
          text: '“He was not asking, ‘What does everyone like?’”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 559465),
          end: Duration(milliseconds: 561240),
          text: 'Nadir replied:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 561240),
          end: Duration(milliseconds: 564777),
          text: '“He was asking, ‘What has Allah taught?’”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 564777),
          end: Duration(milliseconds: 567207),
          text: 'The first mark almost completed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 567207),
          end: Duration(milliseconds: 569637),
          text: 'Then the strange thing happened.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 569637),
          end: Duration(milliseconds: 573422),
          text: 'A small shop appeared at the edge of the street.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 573422),
          end: Duration(milliseconds: 576777),
          text: 'It had not been there a moment earlier.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 576777),
          end: Duration(milliseconds: 579769),
          text: 'Nadir noticed first.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 579769),
          end: Duration(milliseconds: 582009),
          text: '“That does not belong here.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 582009),
          end: Duration(milliseconds: 585969),
          text: 'Akhlaq sighed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 585969),
          end: Duration(milliseconds: 588969),
          text: '“Excellent. The mystery has returned.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 589929),
          end: Duration(milliseconds: 592489),
          text: 'The shop contained no merchant.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 593089),
          end: Duration(milliseconds: 594329),
          text: 'Only a mirror.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 595404),
          end: Duration(milliseconds: 597089),
          text: 'Imaan approached carefully.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 597849),
          end: Duration(milliseconds: 600379),
          text: 'On the mirror were four words:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 600379),
          end: Duration(milliseconds: 602975),
          text: 'EVERYONE CANNOT BE WRONG.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 603840),
          end: Duration(milliseconds: 605447),
          text: 'Akhlaq read them aloud.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 605447),
          end: Duration(milliseconds: 609235),
          text: 'Then looked around the crowded town.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 609235),
          end: Duration(milliseconds: 614972),
          text: 'For one second, the sentence sounded convincing.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 614972),
          end: Duration(milliseconds: 616694),
          text: 'So many people.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 616694),
          end: Duration(milliseconds: 621753),
          text:
              'Surely so many people could not all make the same wrong choice?',
        ),
        CaptionLine(
          start: Duration(milliseconds: 621753),
          end: Duration(milliseconds: 626071),
          text: 'Then Imaan remembered Nuh (A.S.).',
        ),
        CaptionLine(
          start: Duration(milliseconds: 626071),
          end: Duration(milliseconds: 630389),
          text: '“Only a few people followed Nuh.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 630389),
          end: Duration(milliseconds: 633988),
          text: 'Akhlaq remembered Hud (A.S.).',
        ),
        CaptionLine(
          start: Duration(milliseconds: 633988),
          end: Duration(milliseconds: 638306),
          text: '“And most of ‘Ad rejected him.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 638306),
          end: Duration(milliseconds: 639745),
          text: 'Nadir added:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 639745),
          end: Duration(milliseconds: 643745),
          text: '“And Ibrahim stood against the beliefs of his whole people.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 644301),
          end: Duration(milliseconds: 646745),
          text: 'Imaan looked at the mirror again.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 646745),
          end: Duration(milliseconds: 650745),
          text: '“So numbers do not decide truth.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 650745),
          end: Duration(milliseconds: 653745),
          text: 'The words on the mirror changed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 653745),
          end: Duration(milliseconds: 655745),
          text: 'TIMES HAVE CHANGED.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 656745),
          end: Duration(milliseconds: 657745),
          text: 'Akhlaq frowned.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 657745),
          end: Duration(milliseconds: 659737),
          text: '“Does that change what Allah teaches?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 659737),
          end: Duration(milliseconds: 663417),
          text: '“No,” Imaan replied.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 663417),
          end: Duration(milliseconds: 665257),
          text: 'The mirror changed again.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 665257),
          end: Duration(milliseconds: 668617),
          text: 'WHY SHOULD ANYONE FEEL ASHAMED?',
        ),
        CaptionLine(
          start: Duration(milliseconds: 668617),
          end: Duration(milliseconds: 670975),
          text: 'This time Nadir answered.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 670975),
          end: Duration(milliseconds: 674457),
          text: '“Haya is not being ashamed of existing.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 674457),
          end: Duration(milliseconds: 676537),
          text: 'The children looked at him.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 676537),
          end: Duration(milliseconds: 684049),
          text:
              '“It means having modesty and knowing that some behaviour should remain within the boundaries Allah has set.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 684631),
          end: Duration(milliseconds: 685329),
          text: 'Imaan nodded.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 685329),
          end: Duration(milliseconds: 690049),
          text:
              '“So we should not teach children to feel ashamed of themselves.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 690049),
          end: Duration(milliseconds: 691169),
          text: '“No.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 691169),
          end: Duration(milliseconds: 696809),
          text:
              '“But we should learn to feel uncomfortable with doing something Allah has clearly forbidden.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 696809),
          end: Duration(milliseconds: 697809),
          text: '“Yes.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 697809),
          end: Duration(milliseconds: 699209),
          text: 'The mirror cracked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 699721),
          end: Duration(milliseconds: 702221),
          text: 'Then shattered without making a sound.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 702221),
          end: Duration(milliseconds: 705321),
          text: 'Behind it was one final sentence:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 705321),
          end: Duration(milliseconds: 710721),
          text:
              'THE FIRST THING WRONGDOING WANTS IS TO STOP BEING CALLED WRONG.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 710721),
          end: Duration(milliseconds: 712521),
          text: 'The shop vanished.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 712521),
          end: Duration(milliseconds: 715321),
          text: 'The first mark on the Compass completed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 715321),
          end: Duration(milliseconds: 717641),
          text: 'The dreamworld began fading.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 717641),
          end: Duration(milliseconds: 722753),
          text:
              'But before they returned, Imaan looked once more towards Lut (A.S.).',
        ),
        CaptionLine(
          start: Duration(milliseconds: 722753),
          end: Duration(milliseconds: 724231),
          text: 'He was still speaking.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 724231),
          end: Duration(milliseconds: 725216),
          text: 'Still warning.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 725216),
          end: Duration(milliseconds: 730233),
          text:
              'Still standing against something his town had learned to accept.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 730233),
          end: Duration(milliseconds: 735793),
          text:
              'She suddenly understood why this story had come immediately after Ibrahim (A.S.).',
        ),
        CaptionLine(
          start: Duration(milliseconds: 735793),
          end: Duration(milliseconds: 740920),
          text:
              'Ibrahim had stood against idols when almost everyone around him accepted them.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 741244),
          end: Duration(milliseconds: 747266),
          text:
              'Lut stood against another kind of wrongdoing when almost everyone around him accepted it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 747266),
          end: Duration(milliseconds: 748602),
          text: 'Different tests.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 748602),
          end: Duration(milliseconds: 750033),
          text: 'The same question.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 750033),
          end: Duration(milliseconds: 756489),
          text:
              'Would Allah’s guidance remain the standard when society wanted another standard?',
        ),
        CaptionLine(
          start: Duration(milliseconds: 756489),
          end: Duration(milliseconds: 758191),
          text: 'The town disappeared.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 758191),
          end: Duration(milliseconds: 762530),
          text: 'They landed back inside Ibn Kathir’s library.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 763269),
          end: Duration(milliseconds: 765485),
          text: 'Akhlaq immediately sat down.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 765485),
          end: Duration(milliseconds: 767949),
          text: '“That was uncomfortable.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 767949),
          end: Duration(milliseconds: 770234),
          text: 'Ibn Kathir looked at him.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 770234),
          end: Duration(milliseconds: 771733),
          text: '“Some lessons are.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 772161),
          end: Duration(milliseconds: 773446),
          text: 'Imaan sat beside him.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 773446),
          end: Duration(milliseconds: 777870),
          text: '“I think children need to understand this carefully.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 777870),
          end: Duration(milliseconds: 781169),
          text: '“How would you explain it?” Ibn Kathir asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 781169),
          end: Duration(milliseconds: 782869),
          text: 'She thought for a moment.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 782869),
          end: Duration(milliseconds: 783486),
          text: 'Then said:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 783795),
          end: Duration(milliseconds: 799209),
          text:
              '“Allah had taught people the right boundaries for relationships between men and women. But many people in Lut’s town ignored those boundaries. What was wrong slowly became so common that people stopped feeling ashamed of it.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 799209),
          end: Duration(milliseconds: 799609),
          text: 'Ibn Kathir nodded.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 799609),
          end: Duration(milliseconds: 799615),
          text: 'Akhlaq added:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 799615),
          end: Duration(milliseconds: 799645),
          text:
              '“But we should not describe everything they were doing in detail.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 799645),
          end: Duration(milliseconds: 799681),
          text:
              '“No,” said Imaan. “We only need to understand the boundary and the lesson.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 799681),
          end: Duration(milliseconds: 806681),
          text: 'Nadir looked towards the Compass.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 806681),
          end: Duration(milliseconds: 818081),
          text: '“And that popularity does not change the boundary.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 818081),
          end: Duration(milliseconds: 820444),
          text: 'The mysterious journal opened.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 820444),
          end: Duration(milliseconds: 821859),
          text: 'Ink appeared:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 821859),
          end: Duration(milliseconds: 823530),
          text: 'ONE MARK IS OPEN.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 823530),
          end: Duration(milliseconds: 824044),
          text: 'Then:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 824044),
          end: Duration(milliseconds: 826230),
          text: 'WRONG BECAME COMMON.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 826230),
          end: Duration(milliseconds: 828673),
          text: 'A second line appeared:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 828673),
          end: Duration(milliseconds: 834104),
          text: 'NEXT, SOMETHING WRONG WILL TRY TO ENTER WITHOUT KNOCKING.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 834797),
          end: Duration(milliseconds: 836531),
          text: 'Akhlaq stared at the page.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 836531),
          end: Duration(milliseconds: 838793),
          text: '“What does that mean?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 838793),
          end: Duration(milliseconds: 845264),
          text:
              'The Compass suddenly pointed towards a small glowing rectangle lying on the desk.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 845264),
          end: Duration(milliseconds: 845886),
          text: 'A phone.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 845886),
          end: Duration(milliseconds: 847545),
          text: 'Its screen flashed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 847545),
          end: Duration(milliseconds: 849450),
          text: 'A message appeared:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 849450),
          end: Duration(milliseconds: 852665),
          text: 'LOOK AT THIS. EVERYONE HAS SEEN IT.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 853271),
          end: Duration(milliseconds: 854885),
          text: 'Akhlaq reached towards it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 855289),
          end: Duration(milliseconds: 856702),
          text: 'Imaan grabbed his hand.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 856702),
          end: Duration(milliseconds: 857106),
          text: '“Don’t.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 857106),
          end: Duration(milliseconds: 859225),
          text: 'The screen flashed again.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 859657),
          end: Duration(milliseconds: 861657),
          text: 'ARE YOU SCARED?',
        ),
        CaptionLine(
          start: Duration(milliseconds: 861657),
          end: Duration(milliseconds: 865097),
          text: 'Nadir looked towards the second mark on the Compass.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 865097),
          end: Duration(milliseconds: 867097),
          text: 'It had begun glowing.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 867623),
          end: Duration(milliseconds: 868937),
          text: 'Imaan understood.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 868937),
          end: Duration(milliseconds: 872777),
          text: 'The next battle would not begin in an ancient street.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 872777),
          end: Duration(milliseconds: 875457),
          text: 'It would begin with a screen.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 875457),
          end: Duration(milliseconds: 879377),
          text: 'Challenge of the Day: Common Does Not Mean Right',
        ),
        CaptionLine(
          start: Duration(milliseconds: 879649),
          end: Duration(milliseconds: 886649),
          text:
              'Today, notice one moment when people around you are doing something you know is wrong.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 886649),
          end: Duration(milliseconds: 897413),
          text:
              'It might be laughing at an inappropriate joke, watching something they should not watch, mocking another child, using bad language, cheating, or saying:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 897413),
          end: Duration(milliseconds: 898929),
          text: '“Everyone does it.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 898929),
          end: Duration(milliseconds: 902465),
          text: 'Do not join simply because the group accepts it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 902465),
          end: Duration(milliseconds: 903312),
          text: 'You can say:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 903312),
          end: Duration(milliseconds: 905101),
          text: '“No, I don’t want to do that.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 905101),
          end: Duration(milliseconds: 907297),
          text: 'Then move away calmly.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 907297),
          end: Duration(milliseconds: 908151),
          text: 'Level-Up',
        ),
        CaptionLine(
          start: Duration(milliseconds: 908151),
          end: Duration(milliseconds: 909737),
          text: 'If someone asks:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 909737),
          end: Duration(milliseconds: 912421),
          text: '“Why are you being so strict?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 912421),
          end: Duration(milliseconds: 915580),
          text: 'Do not insult them.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 915580),
          end: Duration(milliseconds: 917475),
          text: 'Simply say:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 917475),
          end: Duration(milliseconds: 924633),
          text:
              '“I don’t think everything becomes right just because lots of people do it.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 924633),
          end: Duration(milliseconds: 934532),
          text:
              'Right and wrong are not decided by popularity. A believer learns Allah’s guidance and has the courage to follow it.',
        ),
      ],
