        CaptionLine(
          start: Duration(milliseconds: 411653),
          end: Duration(milliseconds: 414573),
          text: 'The child raised his hand.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 414573),
          end: Duration(milliseconds: 416293),
          text: 'Then stopped.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 416293),
          end: Duration(milliseconds: 418653),
          text: 'He took a step back.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 418653),
          end: Duration(milliseconds: 419732),
          text: '“I’m angry.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 419732),
          end: Duration(milliseconds: 423893),
          text: 'He called for his father instead.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 423893),
          end: Duration(milliseconds: 425831),
          text: 'The Compass flashed:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 425831),
          end: Duration(milliseconds: 431005),
          text: 'FEELING ANGRY IS NOT THE SAME AS CHOOSING TO HURT.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 431005),
          end: Duration(milliseconds: 432514),
          text: 'Another scene.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 432514),
          end: Duration(milliseconds: 435782),
          text: 'A child found money on the floor.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 435782),
          end: Duration(milliseconds: 438422),
          text: '“I really want to keep this.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 438422),
          end: Duration(milliseconds: 441145),
          text: 'Then he took it to a teacher.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 441145),
          end: Duration(milliseconds: 444845),
          text: 'WANTING MONEY DOES NOT MAKE IT YOURS.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 444917),
          end: Duration(milliseconds: 445549),
          text: 'Another scene.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 445549),
          end: Duration(milliseconds: 447067),
          text: 'A plate of food.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 447067),
          end: Duration(milliseconds: 449849),
          text: 'A child already had enough.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 449849),
          end: Duration(milliseconds: 452379),
          text: 'The last piece remained.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 452379),
          end: Duration(milliseconds: 455490),
          text: 'His sister reached towards it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 455490),
          end: Duration(milliseconds: 456970),
          text: 'He reached too.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 456970),
          end: Duration(milliseconds: 459560),
          text: 'Then pulled his hand back.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 459560),
          end: Duration(milliseconds: 461040),
          text: '“You can have it.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 461040),
          end: Duration(milliseconds: 464557),
          text: 'WANTING MORE DOES NOT MEAN YOU NEED MORE.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 465470),
          end: Duration(milliseconds: 466313),
          text: 'Imaan smiled.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 466313),
          end: Duration(milliseconds: 470102),
          text: '“The same skill keeps coming back.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 470102),
          end: Duration(milliseconds: 471365),
          text: '“What skill?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 471365),
          end: Duration(milliseconds: 472909),
          text: '“Self-control.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 472909),
          end: Duration(milliseconds: 475575),
          text: 'The Compass carried them back to Lut’s town.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 476365),
          end: Duration(milliseconds: 480709),
          text: 'The people there had not simply made one wrong choice.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 480709),
          end: Duration(milliseconds: 483813),
          text: 'The wrong behaviour had become repeated.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 483813),
          end: Duration(milliseconds: 484901),
          text: 'Then defended.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 484901),
          end: Duration(milliseconds: 485417),
          text: 'Then normalised.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 486707),
          end: Duration(milliseconds: 489804),
          text: 'Then used to pressure others.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 490707),
          end: Duration(milliseconds: 492385),
          text: 'Akhlaq looked towards Lut (A.S.).',
        ),
        CaptionLine(
          start: Duration(milliseconds: 492901),
          end: Duration(milliseconds: 496271),
          text: '“So one wrong choice can become a habit.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 496271),
          end: Duration(milliseconds: 497466),
          text: 'Nadir nodded.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 497466),
          end: Duration(milliseconds: 502901),
          text:
              '“And a habit can become something a person stops questioning.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 502901),
          end: Duration(milliseconds: 504893),
          text: '“And then?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 504893),
          end: Duration(milliseconds: 512073),
          text:
              '“Sometimes they begin defending the habit because giving it up feels harder than admitting it is wrong.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 512473),
          end: Duration(milliseconds: 514073),
          text: 'Imaan looked thoughtful.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 514073),
          end: Duration(milliseconds: 517573),
          text: '“That is why we should correct ourselves early.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 517573),
          end: Duration(milliseconds: 519333),
          text: 'The Compass clicked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 519333),
          end: Duration(milliseconds: 524913),
          text:
              'THE EARLIER YOU CONTROL A WRONG DESIRE, THE LESS CONTROL IT GAINS OVER YOU.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 525721),
          end: Duration(milliseconds: 526676),
          text: 'Akhlaq repeated:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 526676),
          end: Duration(milliseconds: 529303),
          text: '“The earlier you control it…”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 529303),
          end: Duration(milliseconds: 530497),
          text: 'Nadir added:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 530497),
          end: Duration(milliseconds: 532885),
          text: '“…the less it controls you.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 532885),
          end: Duration(milliseconds: 535993),
          text: 'Suddenly, the hooded traveller appeared.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 535993),
          end: Duration(milliseconds: 538725),
          text: 'This time he was closer than before.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 538725),
          end: Duration(milliseconds: 541551),
          text: 'His reversed Compass glowed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 541551),
          end: Duration(milliseconds: 543199),
          text: 'A message formed:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 543199),
          end: Duration(milliseconds: 545877),
          text: 'YOUR FEELINGS ARE YOUR TRUTH.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 546447),
          end: Duration(milliseconds: 548157),
          text: 'Imaan shook her head.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 548157),
          end: Duration(milliseconds: 549157),
          text: '“No.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 549157),
          end: Duration(milliseconds: 550917),
          text: 'The message changed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 550917),
          end: Duration(milliseconds: 553877),
          text: 'IF YOU FEEL IT STRONGLY, FOLLOW IT.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 554549),
          end: Duration(milliseconds: 556277),
          text: 'Akhlaq looked at the message.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 556277),
          end: Duration(milliseconds: 559157),
          text: 'Then at the examples they had just seen.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 559157),
          end: Duration(milliseconds: 560157),
          text: 'Anger.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 560157),
          end: Duration(milliseconds: 561157),
          text: 'Greed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 561157),
          end: Duration(milliseconds: 562157),
          text: 'Curiosity.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 562157),
          end: Duration(milliseconds: 563157),
          text: 'Jealousy.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 563157),
          end: Duration(milliseconds: 563657),
          text: 'Screens.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 564869),
          end: Duration(milliseconds: 565669),
          text: 'Food.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 565669),
          end: Duration(milliseconds: 568869),
          text: 'Forbidden desires.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 568869),
          end: Duration(milliseconds: 575869),
          text:
              '“If that rule were true,” he said slowly, “then every strong feeling would become permission.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 575869),
          end: Duration(milliseconds: 577336),
          text: 'Nadir nodded.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 578269),
          end: Duration(milliseconds: 580869),
          text: 'The dark Compass flashed again:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 580869),
          end: Duration(milliseconds: 584389),
          text: 'DENYING A DESIRE MEANS DENYING YOURSELF.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 585277),
          end: Duration(milliseconds: 587941),
          text: 'Imaan looked towards Lut (A.S.).',
        ),
        CaptionLine(
          start: Duration(milliseconds: 587941),
          end: Duration(milliseconds: 589701),
          text: '“No.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 589701),
          end: Duration(milliseconds: 591461),
          text: 'She spoke clearly.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 591461),
          end: Duration(milliseconds: 596501),
          text:
              '“Controlling a desire does not mean pretending you do not feel it.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 597551),
          end: Duration(milliseconds: 598301),
          text: 'Akhlaq added:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 598301),
          end: Duration(milliseconds: 602641),
          text: '“It means the feeling does not get to decide everything.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 602641),
          end: Duration(milliseconds: 604853),
          text: 'Their own Compass glowed:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 604853),
          end: Duration(milliseconds: 608633),
          text: 'YOU ARE MORE THAN WHAT YOU FEEL IN ONE MOMENT.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 608633),
          end: Duration(milliseconds: 610973),
          text: 'The hooded figure stepped backwards.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 610973),
          end: Duration(milliseconds: 614813),
          text: 'Then his Compass displayed one final line:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 614813),
          end: Duration(milliseconds: 619253),
          text:
